SELECT shape
FROM bricks JOIN boxes
ON weight > min_weight;

SELECT shape
FROM bricks JOIN boxes
ON weight < max_weight;

SELECT shape
FROM bricks JOIN boxes
ON NOT weight > max_weight;

SELECT shape
FROM bricks JOIN boxes
ON weight BETWEEN min_weight AND max_weight;

SELECT *
FROM employees
WHERE salary > AVG(salary) OVER (
PARTITION BY department_id
);

SELECT *
FROM (
SELECT e.*,
 AVG(salary) OVER (
 PARTITION BY department_id
) avg_sal
 FROM employees e
)
WHERE salary > avg_sal;

